# -*- coding: utf-8 -*-
import os, struct, zlib, base64

BASE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "frontend")

def w(path, content):
    full = os.path.join(BASE, path)
    d = os.path.dirname(full)
    if d: os.makedirs(d, exist_ok=True)
    open(full, "w", encoding="utf-8").write(content)
    print("  created " + path)

def wb(path, data):
    full = os.path.join(BASE, path)
    d = os.path.dirname(full)
    if d: os.makedirs(d, exist_ok=True)
    open(full, "wb").write(data)
    print("  created " + path)

def make_png(pw, ph, r, g, b):
    def chunk(ct, data):
        c = ct + data
        return struct.pack(">I", len(data)) + c + struct.pack(">I", zlib.crc32(c) & 0xffffffff)
    raw = b""
    for _ in range(ph):
        raw += b"\x00" + bytes([r,g,b]) * pw
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", pw, ph, 8, 2, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b"")

